sp_widget.css:
.wei-landing {
  font-family: Arial, sans-serif;
  color: #1A1A1A;
}

/* Navigation */
.wei-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 32px;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.06);
  position: sticky;
  top: 0;
  z-index: 10;
}

.wei-logo {
  font-weight: 700;
  font-size: 18px;
  white-space: nowrap;
}

.wei-logo-accent {
  color: #FF5A1F;
}

.wei-nav-links {
  display: flex;
  align-items: center;
}

.wei-nav-links a {
  margin: 0 14px;
  text-decoration: none;
  color: #333;
  font-size: 14px;
  font-weight: 500;
}

.wei-nav-links a:hover {
  color: #FF5A1F;
}

.wei-nav-auth {
  display: flex;
  align-items: center;
  font-size: 13px;
}

/* Buttons */
.wei-btn {
  display: inline-block;
  border-radius: 24px;
  padding: 8px 20px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  text-decoration: none;
}

.wei-btn-primary {
  background: #FF5A1F;
  color: #fff;
}

.wei-btn-primary:hover {
  background: #E94E17;
  color: #fff;
}

.wei-btn-outline {
  border: 1.5px solid #FF5A1F;
  color: #FF5A1F;
  background: transparent;
}

.wei-btn-outline:hover {
  background: #FF5A1F;
  color: #fff;
}

.wei-btn-ghost {
  background: #F3F3F3;
  color: #1A1A1A;
}

.wei-btn-ghost:hover {
  background: #E8E8E8;
}

/* Hero */
.wei-hero {
  text-align: center;
  padding: 72px 24px;
  color: #fff;
  background: linear-gradient(
    135deg,
    #1A1A1A 0%,
    #3A2416 60%,
    #FF5A1F 140%
  );
}

.wei-hero-badge {
  display: inline-block;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  padding: 6px 16px;
  font-size: 12px;
  margin-bottom: 16px;
}

.wei-hero h1 {
  font-size: 34px;
  font-weight: 700;
  max-width: 680px;
  margin: 0 auto 16px;
  line-height: 1.25;
}

.wei-hero p {
  font-size: 15px;
  opacity: 0.85;
  max-width: 560px;
  margin: 0 auto 28px;
  line-height: 1.6;
}

.wei-hero-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.wei-hero-trust {
  display: flex;
  justify-content: center;
  gap: 20px;
  font-size: 12px;
  opacity: 0.8;
  flex-wrap: wrap;
}

/* Sections */
.wei-section {
  padding: 56px 24px;
  max-width: 1040px;
  margin: 0 auto;
}

.wei-section h2 {
  font-size: 26px;
  font-weight: 700;
  text-align: center;
  margin: 0 0 8px;
}

.wei-section-sub {
  text-align: center;
  color: #666;
  font-size: 14px;
  margin-bottom: 36px;
}

/* Section 1 - Stats */
.wei-stats-section {
  display: flex;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.wei-stat-card {
  text-align: center;
  min-width: 120px;
}

.wei-stat-number {
  font-size: 32px;
  font-weight: 700;
  color: #FF5A1F;
}

.wei-stat-label {
  font-size: 13px;
  color: #555;
  margin-top: 4px;
}

/* Section 2 - Steps */
.wei-steps-row {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  justify-content: center;
}

.wei-step-card {
  flex: 1;
  min-width: 220px;
  max-width: 260px;
  text-align: center;
  padding: 24px 16px;
  border-radius: 12px;
  background: #FAFAFA;
  border: 1px solid #EEE;
}

.wei-step-number {
  width: 36px;
  height: 36px;
  line-height: 36px;
  border-radius: 50%;
  background: #FF5A1F;
  color: #fff;
  font-weight: 700;
  margin: 0 auto 14px;
}

.wei-step-title {
  font-weight: 600;
  font-size: 15px;
  margin-bottom: 6px;
}

.wei-step-desc {
  font-size: 13px;
  color: #666;
  line-height: 1.5;
}

/* Section 3 - Features */
.wei-features-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
}

.wei-feature-card {
  background: #fff;
  border: 1px solid #EEE;
  border-radius: 12px;
  padding: 20px 16px;
  text-align: center;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03);
}

.wei-feature-icon {
  font-size: 24px;
  margin-bottom: 10px;
}

.wei-feature-title {
  font-weight: 600;
  font-size: 14px;
  margin-bottom: 6px;
}

.wei-feature-desc {
  font-size: 12px;
  color: #666;
  line-height: 1.5;
}

/* Footer */
.wei-footer {
  background: #1A1A1A;
  color: #ccc;
  padding: 48px 24px 24px;
}

.wei-footer-columns {
  display: flex;
  justify-content: center;
  gap: 64px;
  flex-wrap: wrap;
  margin-bottom: 32px;
}

.wei-footer-col {
  min-width: 140px;
}

.wei-footer-heading {
  color: #fff;
  font-weight: 600;
  font-size: 13px;
  margin-bottom: 12px;
}

.wei-footer-col a {
  display: block;
  color: #999;
  font-size: 13px;
  text-decoration: none;
  margin-bottom: 8px;
}

.wei-footer-col a:hover {
  color: #FF5A1F;
}

.wei-footer-bottom {
  text-align: center;
  font-size: 12px;
  color: #777;
  border-top: 1px solid #333;
  padding-top: 20px;
}

/* Service Portal responsive layout */
@media (max-width: 700px) {

  .wei-nav {
    flex-wrap: wrap;
    padding: 14px 20px;
    gap: 12px;
  }

  .wei-nav-links {
    order: 3;
    width: 100%;
    justify-content: center;
  }

  .wei-nav-links a {
    margin: 0 8px;
  }

  .wei-features-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .wei-hero {
    padding: 56px 20px;
  }

  .wei-hero h1 {
    font-size: 26px;
  }

  .wei-footer-columns {
    gap: 32px;
  }
}

@media (max-width: 450px) {

  .wei-nav {
    justify-content: center;
  }

  .wei-logo {
    width: 100%;
    text-align: center;
  }

  .wei-nav-links {
    flex-wrap: wrap;
  }

  .wei-features-grid {
    grid-template-columns: 1fr;
  }

  .wei-hero-actions {
    flex-direction: column;
    align-items: center;
  }

  .wei-btn {
    width: 220px;
  }

  .wei-stats-section {
    gap: 28px;
  }
}

sp_widget.script:
(function() {

    // Impact statistics
    data.impactStats = [
        {
            value: '55%+',
            label: 'Faster exception detection'
        },
        {
            value: '50%+',
            label: 'Faster resolution time'
        },
        {
            value: '95%+',
            label: 'Resolution rate'
        }
    ];


    // How it works
    data.howItWorks = [
        {
            title: 'Report',
            desc: 'Staff log the issue with type, location, and evidence in seconds.'
        },
        {
            title: 'Classify & route',
            desc: 'AI sets severity and sends it straight to the right owner.'
        },
        {
            title: 'Resolve',
            desc: 'Technicians act, verify, and close with a full audit trail.'
        }
    ];


    // Features
    data.features = [
        {
            icon: '⚡',
            title: 'Faster response',
            desc: 'Automated routing reaches the right owner without delay.'
        },
        {
            icon: '🎯',
            title: 'Increased accountability',
            desc: 'Clear ownership and status tracking, nothing dropped.'
        },
        {
            icon: '🧠',
            title: 'Smarter classification',
            desc: 'AI-based categorization reduces manual triage errors.'
        },
        {
            icon: '📊',
            title: 'Real-time visibility',
            desc: 'Supervisors see open, in-progress, and resolved at a glance.'
        }
    ];


    // Login information
    data.isLoggedIn = !gs.isGuestUser();

    if (data.isLoggedIn) {
        data.userName = gs.getUserDisplayName();

        // Determine user role
        if (gs.hasRole('wei_supervisor')) {
            data.userRole = 'Supervisor';

        } else if (gs.hasRole('wei_technician')) {
            data.userRole = 'Technician';

        } else if (gs.hasRole('wei_admin')) {
            data.userRole = 'Admin';

        } else {
            data.userRole = 'Staff';
        }

    } else {
        data.userName = '';
        data.userRole = '';
    }

})();
